#!/usr/bin/env python3
"""Script to examine PDF form fields"""

import PyPDF2

def examine_pdf_fields(pdf_path):
    """Examine all form fields in a PDF"""
    with open(pdf_path, 'rb') as file:
        pdf_reader = PyPDF2.PdfReader(file)

        # Get form fields
        if '/AcroForm' in pdf_reader.trailer['/Root']:
            fields = pdf_reader.get_fields()

            if fields:
                print(f"Found {len(fields)} form fields:\n")
                for field_name, field_info in sorted(fields.items()):
                    field_type = field_info.get('/FT', 'Unknown')
                    field_value = field_info.get('/V', '')
                    print(f"Field: {field_name}")
                    print(f"  Type: {field_type}")
                    print(f"  Current Value: {field_value}")
                    print()
            else:
                print("No form fields found in PDF")
        else:
            print("PDF does not contain a form")

if __name__ == "__main__":
    examine_pdf_fields("/root/sc100-blank.pdf")

