"""Script to examine PDF form fields using PyMuPDF"""

import fitz  # PyMuPDF

def examine_pdf_fields(pdf_path):
    """Examine all form fields in a PDF"""
    doc = fitz.open(pdf_path)

    print(f"PDF has {len(doc)} pages\n")

    for page_num in range(len(doc)):
        page = doc[page_num]
        widgets = page.widgets()

