"""Script to verify filled form fields"""

import fitz  # PyMuPDF

def verify_filled_form(pdf_path):
    """Display all filled form fields"""
    doc = fitz.open(pdf_path)

    print("FILLED FORM FIELDS:\n" + "="*70 + "\n")

    for page_num in range(len(doc)):
        page = doc[page_num]
        widgets = list(page.widgets())

        for widget in widgets:
            if widget.field_value and str(widget.field_value).strip():
                print(f"Page {page_num + 1}:")
                print(f"  Label: {widget.field_label}")
                print(f"  Value: {widget.field_value}")
                print()

    doc.close()

if __name__ == "__main__":
    verify_filled_form("/root/sc100-filled.pdf")

